//! Daemon configuration (generated by the NixOS module) and the trust check
//! for the secrets file.

use crate::bail;
use crate::error::{Error, Result};
use crate::proto::GpgCacheLimits;
use serde::Deserialize;
use std::collections::BTreeMap;
use std::os::unix::fs::MetadataExt;
use std::path::Path;

#[derive(Deserialize, Debug, Default, Clone)]
#[serde(default)]
pub struct Profile {
    pub description: String,
    pub command: String,
    pub fixed_args: Vec<String>,
    /// ENV_VAR -> dotted key in the sops file
    pub env: BTreeMap<String, String>,
    pub extra_env: BTreeMap<String, String>,
    /// PATH for the child
    pub path: String,
    pub allow: Vec<Vec<String>>,
    pub deny: Vec<Vec<String>>,
    pub timeout_seconds: u64,
}

#[derive(Deserialize, Debug, Clone)]
#[serde(default)]
pub struct Config {
    pub secrets_file: String,
    pub state_dir: String,
    pub allowed_users: Vec<String>,
    pub default_ttl_seconds: u64,
    pub max_ttl_seconds: u64,
    pub redact_output: bool,
    pub gpg_cache_limits: GpgCacheLimits,
    pub profiles: BTreeMap<String, Profile>,
    pub approval: Approval,
}

/// Quick approval of a sealed session (secrets already in memory).
#[derive(Deserialize, Debug, Clone)]
#[serde(default)]
pub struct Approval {
    /// How long a dialog waits for the user.
    pub timeout_seconds: u64,
    /// Forget (wipe) sealed secrets after this long; 0 = keep until reboot
    /// or `secret-broker lock --forget`.
    pub sealed_max_seconds: u64,
    pub pin: PinConfig,
    pub fido2: Fido2Config,
    /// Extra PAM-based methods (fingerprint, ...), checked in a helper process.
    pub pam: Vec<PamMethod>,
}

impl Default for Approval {
    fn default() -> Self {
        Approval {
            timeout_seconds: 120,
            sealed_max_seconds: 0,
            pin: PinConfig::default(),
            fido2: Fido2Config::default(),
            pam: Vec::new(),
        }
    }
}

#[derive(Deserialize, Debug, Clone)]
#[serde(default)]
pub struct PinConfig {
    pub enable: bool,
    pub min_length: usize,
    /// Wrong PINs before the secrets are wiped from memory (back to gpg).
    pub max_attempts: u32,
    pub argon2_memory_kib: u32,
    pub argon2_iterations: u32,
    pub argon2_parallelism: u32,
}

impl Default for PinConfig {
    fn default() -> Self {
        let c = crate::pin::Cost::default();
        PinConfig {
            enable: true,
            min_length: 6,
            max_attempts: 5,
            argon2_memory_kib: c.m_kib,
            argon2_iterations: c.t,
            argon2_parallelism: c.p,
        }
    }
}

impl PinConfig {
    pub fn cost(&self) -> crate::pin::Cost {
        crate::pin::Cost {
            m_kib: self.argon2_memory_kib,
            t: self.argon2_iterations,
            p: self.argon2_parallelism,
        }
    }
}

#[derive(Deserialize, Debug, Clone)]
#[serde(default)]
pub struct Fido2Config {
    /// Relying party id the credentials were made for.
    pub rp_id: String,
    /// Directory holding fido2-token and fido2-assert (libfido2 tools).
    pub tools_dir: String,
    pub credentials: Vec<Fido2Credential>,
}

impl Default for Fido2Config {
    fn default() -> Self {
        Fido2Config {
            rp_id: "secret-broker".into(),
            tools_dir: String::new(),
            credentials: Vec::new(),
        }
    }
}

#[derive(Deserialize, Debug, Clone, Default)]
#[serde(default)]
pub struct Fido2Credential {
    pub name: String,
    /// Base64 credential id from `secret-broker fido2-enroll`.
    pub id: String,
    /// PEM public key file.
    pub public_key_file: String,
    /// es256 | rs256 | eddsa
    #[serde(rename = "type")]
    pub kind: String,
}

#[derive(Deserialize, Debug, Clone, Default)]
#[serde(default)]
pub struct PamMethod {
    /// Method name shown in status, e.g. "fingerprint".
    pub name: String,
    /// /etc/pam.d service to authenticate against.
    pub service: String,
    /// Hint shown in the dialog, e.g. "Touch the fingerprint sensor".
    pub label: String,
    /// Attempts per approval.
    pub retries: u32,
}

impl Default for Config {
    fn default() -> Self {
        Config {
            secrets_file: String::new(),
            state_dir: "/var/lib/secret-broker".into(),
            allowed_users: Vec::new(),
            default_ttl_seconds: 8 * 3600,
            max_ttl_seconds: 24 * 3600,
            redact_output: true,
            gpg_cache_limits: GpgCacheLimits {
                default_cache_ttl: 900,
                max_cache_ttl: 7200,
            },
            profiles: BTreeMap::new(),
            approval: Approval::default(),
        }
    }
}

fn valid_name(s: &str) -> bool {
    let mut chars = s.chars();
    matches!(chars.next(), Some(c) if c.is_ascii_alphanumeric())
        && chars.all(|c| c.is_ascii_alphanumeric() || matches!(c, '_' | '.' | '-'))
}

fn valid_env(s: &str) -> bool {
    let mut chars = s.chars();
    matches!(chars.next(), Some(c) if c.is_ascii_alphabetic() || c == '_')
        && chars.all(|c| c.is_ascii_alphanumeric() || c == '_')
}

pub fn load(path: &str) -> Result<Config> {
    let text = std::fs::read(path).map_err(|e| Error::from(e).context(path))?;
    let mut c: Config = serde_json::from_slice(&text).map_err(|e| Error::from(e).context(path))?;
    if !c.secrets_file.starts_with('/') {
        bail!("secrets_file must be an absolute path");
    }
    if c.default_ttl_seconds == 0 {
        c.default_ttl_seconds = 8 * 3600;
    }
    if c.max_ttl_seconds == 0 {
        c.max_ttl_seconds = 24 * 3600;
    }
    c.default_ttl_seconds = c.default_ttl_seconds.min(c.max_ttl_seconds);
    for (name, p) in &c.profiles {
        if !valid_name(name) {
            bail!("invalid profile name {name:?}");
        }
        if !p.command.starts_with('/') {
            bail!("profile {name}: command must be an absolute path");
        }
        if p.allow.is_empty() {
            bail!("profile {name}: needs at least one allow rule (use [[\"**\"]] to allow any arguments)");
        }
        for k in p.env.keys().chain(p.extra_env.keys()) {
            if !valid_env(k) {
                bail!("profile {name}: invalid env var name {k:?}");
            }
        }
    }
    let a = &mut c.approval;
    if a.timeout_seconds == 0 {
        a.timeout_seconds = 120;
    }
    if a.pin.max_attempts == 0 {
        a.pin.max_attempts = 5;
    }
    if a.fido2.rp_id.is_empty() {
        a.fido2.rp_id = "secret-broker".into();
    }
    if !a.fido2.credentials.is_empty() && !a.fido2.tools_dir.starts_with('/') {
        bail!("approval.fido2.tools_dir must be an absolute path");
    }
    for cred in &mut a.fido2.credentials {
        if cred.kind.is_empty() {
            cred.kind = "es256".into();
        }
        if !matches!(cred.kind.as_str(), "es256" | "rs256" | "eddsa") {
            bail!("fido2 credential {}: unknown type {:?}", cred.name, cred.kind);
        }
        if cred.id.is_empty() || !cred.public_key_file.starts_with('/') {
            bail!("fido2 credential {}: needs id and an absolute public_key_file", cred.name);
        }
    }
    for m in &mut a.pam {
        if !valid_name(&m.name) || matches!(m.name.as_str(), "pin" | "fido2") {
            bail!("invalid PAM method name {:?}", m.name);
        }
        if !valid_name(&m.service) {
            bail!("PAM method {}: invalid service {:?}", m.name, m.service);
        }
        if m.retries == 0 {
            m.retries = 3;
        }
        if m.label.is_empty() {
            m.label = format!("Authenticate with {}", m.name);
        }
    }
    Ok(c)
}

/// Refuse a secrets file that a non-root user other than the broker could
/// replace. Files in /nix/store are immutable.
pub fn check_trusted(path: &Path) -> Result<()> {
    check_trusted_depth(path, 0)
}

fn check_trusted_depth(path: &Path, depth: u32) -> Result<()> {
    if depth > 16 {
        bail!("too many symlinks");
    }
    if path.starts_with("/nix/store/") {
        return Ok(());
    }
    let me = crate::sys::getuid();
    let mut cur = Some(path);
    while let Some(p) = cur {
        let md = std::fs::symlink_metadata(p).map_err(|e| Error::from(e).context(p.display()))?;
        if md.file_type().is_symlink() {
            let target =
                std::fs::canonicalize(p).map_err(|e| Error::from(e).context(p.display()))?;
            check_trusted_depth(&target, depth.saturating_add(1))?;
        } else {
            if md.uid() != 0 && md.uid() != me {
                bail!(
                    "{} is owned by uid {}; it must be owned by root (or the broker) or live in /nix/store",
                    p.display(),
                    md.uid()
                );
            }
            let sticky = md.mode() & 0o1000 != 0;
            if md.mode() & 0o022 != 0 && !sticky {
                bail!("{} is group/world writable", p.display());
            }
        }
        cur = p.parent();
    }
    Ok(())
}

#[cfg(test)]
#[allow(clippy::unwrap_used)]
mod tests {
    use super::*;

    #[test]
    fn names() {
        assert!(valid_name("gh") && valid_name("a.b-c_1") && !valid_name("-x") && !valid_name(""));
        assert!(valid_env("GH_TOKEN") && valid_env("_X") && !valid_env("1X") && !valid_env("A-B"));
    }

    #[test]
    fn store_paths_trusted() {
        assert!(check_trusted(Path::new("/nix/store/abc-secrets.json")).is_ok());
    }
}
